1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21	)
22	
23	// Version is the baseline release identifier.
24	const Version = "0.1.0"
25	
26	const metricsPath = "/api/v1/metrics"
27	
28	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
29	
30	type health struct {
31		Status  string `json:"status"`
32		Service string `json:"service"`
33		Version string `json:"version"`
34	}
35	
36	// series is one uniquely identified time series: name + full label set.
37	type series struct {
38		name   string
39		typ    string
40		labels map[string]string
41	
42		// counter/gauge state
43		value float64
44	
45		// histogram state
46		bucketBounds []float64 // strictly increasing, fixed at first write
47		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
48		count        int64
49		sum          float64
50	}
51	
52	type metricStore struct {
53		mu     sync.RWMutex
54		series map[string]*series
55	
56		// alert rules keyed by rule id; guarded by mu so rule replacement and
57		// alert evaluation are atomic with metric commits.
58		rules map[string]*alertRule
59	
60		// silences keyed by silence id; same lock so alert evaluation reads
61		// metrics, rules and silences from one consistent snapshot.
62		silences map[string]*silence
63	
64		// inhibit rules keyed by rule id; same lock so alert evaluation also
65		// reads inhibit rules from the same consistent snapshot.
66		inhibitions map[string]*inhibitRule
67	
68		// notification routes keyed by route id; same lock so the notification
69		// plan reads routes from the same snapshot as alert evaluation.
70		notificationRoutes map[string]*notificationRoute
71	}
72	
73	func newMetricStore() *metricStore {
74		return &metricStore{
75			series:             make(map[string]*series),
76			rules:              make(map[string]*alertRule),
77			silences:           make(map[string]*silence),
78			inhibitions:        make(map[string]*inhibitRule),
79			notificationRoutes: make(map[string]*notificationRoute),
80		}
81	}
82	
83	// validatedSample is a sample that passed all format and value checks.
84	type validatedSample struct {
85		key     string
86		name    string
87		typ     string
88		labels  map[string]string
89		value   float64
90		buckets []float64 // non-nil for histograms
91	}
92	
93	// checkAndApply validates the batch against the current state (and against
94	// itself) and then commits it in array order. A false result signals a type or
95	// bucket-boundary conflict; in that case no state is mutated.
96	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
97		s.mu.Lock()
98		defer s.mu.Unlock()
99	
100		// First pass: conflict detection against committed state and earlier
101		// samples in the same batch.
102		resolved := make(map[string]*series, len(batch))
103		for _, sm := range batch {
104			existing, ok := s.series[sm.key]
105			if !ok {
106				if shadow, seen := resolved[sm.key]; seen {
107					existing, ok = shadow, true
108				}
109			}
110			if ok {
111				if existing.typ != sm.typ {
112					return false
113				}
114				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
115					return false
116				}
117				resolved[sm.key] = existing
118				continue
119			}
120			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
121		}
122	
123		// Second pass: commit in order.
124		for _, sm := range batch {
125			cur, ok := s.series[sm.key]
126			if !ok {
127				cur = &series{
128					name:         sm.name,
129					typ:          sm.typ,
130					labels:       sm.labels,
131					bucketBounds: append([]float64(nil), sm.buckets...),
132				}
133				if sm.typ == "histogram" {
134					cur.bucketCounts = make([]int64, len(sm.buckets))
135				}
136				s.series[sm.key] = cur
137			}
138			switch sm.typ {
139			case "counter":
140				cur.value += sm.value
141			case "gauge":
142				cur.value = sm.value
143			case "histogram":
144				cur.count++
145				cur.sum += sm.value
146				for i, bound := range cur.bucketBounds {
147					if sm.value <= bound {
148						cur.bucketCounts[i]++
149					}
150				}
151			}
152		}
153		return true
154	}
155	
156	type seriesOutput struct {
157		Name    string            `json:"name"`
158		Type    string            `json:"type"`
159		Labels  map[string]string `json:"labels"`
160		Value   *float64          `json:"value,omitempty"`
161		Count   *int64            `json:"count,omitempty"`
162		Sum     *float64          `json:"sum,omitempty"`
163		Buckets []bucketOutput    `json:"buckets,omitempty"`
164	}
165	
166	type bucketOutput struct {
167		LE    float64 `json:"le"`
168		Count int64   `json:"count"`
169	}
170	
171	// query returns matching series as ready-to-encode outputs. A series matches
172	// when its name equals name exactly and it contains every selector label.
173	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
174		s.mu.RLock()
175		defer s.mu.RUnlock()
176	
177		out := make([]seriesOutput, 0)
178		for _, cur := range s.series {
179			if cur.name != name {
180				continue
181			}
182			matched := true
183			for k, v := range selector {
184				got, ok := cur.labels[k]
185				if !ok || got != v {
186					matched = false
187					break
188				}
189			}
190			if !matched {
191				continue
192			}
193			item := seriesOutput{
194				Name:   cur.name,
195				Type:   cur.typ,
196				Labels: copyLabels(cur.labels),
197			}
198			switch cur.typ {
199			case "counter", "gauge":
200				v := cur.value
201				item.Value = &v
202			case "histogram":
203				c, sum := cur.count, cur.sum
204				item.Count = &c
205				item.Sum = &sum
206				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
207				for i, bound := range cur.bucketBounds {
208					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
209				}
210			}
211			out = append(out, item)
212		}
213	
214		sort.Slice(out, func(i, j int) bool {
215			return compareLabels(out[i].Labels, out[j].Labels) < 0
216		})
217		return out
218	}
219	
220	// compareLabels imposes a normalized lexicographic order on full label sets:
221	// keys are sorted, then (key, value) pairs are compared element-wise, and a
222	// shorter pair list sorts first when it is a prefix of a longer one.
223	func compareLabels(a, b map[string]string) int {
224		ka := sortedKeys(a)
225		kb := sortedKeys(b)
226		n := len(ka)
227		if len(kb) < n {
228			n = len(kb)
229		}
230		for i := 0; i < n; i++ {
231			if ka[i] != kb[i] {
232				return strings.Compare(ka[i], kb[i])
233			}
234			if a[ka[i]] != b[kb[i]] {
235				return strings.Compare(a[ka[i]], b[kb[i]])
236			}
237		}
238		switch {
239		case len(ka) < len(kb):
240			return -1
241		case len(ka) > len(kb):
242			return 1
243		default:
244			return 0
245		}
246	}
247	
248	func sortedKeys(m map[string]string) []string {
249		keys := make([]string, 0, len(m))
250		for k := range m {
251			keys = append(keys, k)
252		}
253		sort.Strings(keys)
254		return keys
255	}
256	
257	func copyLabels(in map[string]string) map[string]string {
258		out := make(map[string]string, len(in))
259		for k, v := range in {
260			out[k] = v
261		}
262		return out
263	}
264	
265	// seriesKey builds a collision-free identity from name + unordered labels.
266	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
267	// so length-prefixed values remove any ambiguity from arbitrary label values.
268	func seriesKey(name string, labels map[string]string) string {
269		var b strings.Builder
270		b.WriteString(name)
271		for _, k := range sortedKeys(labels) {
272			b.WriteByte(0)
273			b.WriteString(k)
274			b.WriteByte(0)
275			v := labels[k]
276			b.WriteString(strconv.Itoa(len(v)))
277			b.WriteByte(0)
278			b.WriteString(v)
279		}
280		return b.String()
281	}
282	
283	func equalBuckets(a, b []float64) bool {
284		if len(a) != len(b) {
285			return false
286		}
287		for i := range a {
288			if a[i] != b[i] {
289				return false
290			}
291		}
292		return true
293	}
294	
295	// Handler returns the HTTP surface served by SignalWatch.
296	func Handler() http.Handler {
297		mux := http.NewServeMux()
298		store := newMetricStore()
299	
300		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
301			if r.Method != http.MethodGet {
302				w.Header().Set("Allow", http.MethodGet)
303				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
304				return
305			}
306			w.Header().Set("Content-Type", "application/json; charset=utf-8")
307			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
308		})
309	
310		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
311			switch r.Method {
312			case http.MethodGet:
313				handleMetricsGet(w, r, store)
314			case http.MethodPost:
315				handleMetricsPost(w, r, store)
316			default:
317				w.Header().Set("Allow", "GET, POST")
318				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
319			}
320		})
321	
322		registerAlertHandlers(mux, store)
323		registerSilenceHandlers(mux, store)
324		registerInhibitHandlers(mux, store)
325		registerNotificationRouteHandlers(mux, store)
326	
327		return mux
328	}
329	
330	func handleMetricsPost(w http.ResponseWriter, r *http.Request, store *metricStore) {
331		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
332		if err != nil || mediaType != "application/json" {
333			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
334			return
335		}
336	
337		body, err := io.ReadAll(r.Body)
338		if err != nil {
339			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
340			return
341		}
342	
343		batch, ok := decodeMetricsBatch(body)
344		if !ok {
345			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
346			return
347		}
348	
349		if !store.checkAndApply(batch) {
350			writeAPIError(w, "metric_conflict", http.StatusConflict)
351			return
352		}
353	
354		w.Header().Set("Content-Type", "application/json; charset=utf-8")
355		w.WriteHeader(http.StatusAccepted)
356		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
357	}
358	
359	type metricsEnvelope struct {
360		Samples *[]json.RawMessage `json:"samples"`
361	}
362	
363	type rawSample struct {
364		Name    *string            `json:"name"`
365		Type    *string            `json:"type"`
366		Labels  *map[string]string `json:"labels"`
367		Value   *float64           `json:"value"`
368		Buckets *[]float64         `json:"buckets"`
369	}
370	
371	// decodeMetricsBatch performs every format and value check. It never returns a
372	// partially validated batch.
373	func decodeMetricsBatch(body []byte) ([]validatedSample, bool) {
374		var env metricsEnvelope
375		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
376			return nil, false
377		}
378	
379		batch := make([]validatedSample, 0, len(*env.Samples))
380		for _, raw := range *env.Samples {
381			var sm rawSample
382			if !strictDecode(raw, &sm) {
383				return nil, false
384			}
385			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
386				return nil, false
387			}
388			name, typ := *sm.Name, *sm.Type
389			if !identPattern.MatchString(name) {
390				return nil, false
391			}
392			if typ != "counter" && typ != "gauge" && typ != "histogram" {
393				return nil, false
394			}
395			labels := *sm.Labels
396			if labels == nil {
397				return nil, false // explicit null labels
398			}
399			for k := range labels {
400				if !identPattern.MatchString(k) {
401					return nil, false
402				}
403			}
404			value := *sm.Value
405			if math.IsNaN(value) || math.IsInf(value, 0) {
406				return nil, false // encoding/json already rejects NaN/Inf tokens
407			}
408			if typ == "counter" && value < 0 {
409				return nil, false
410			}
411	
412			var buckets []float64
413			if typ == "histogram" {
414				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
415					return nil, false
416				}
417				buckets = append([]float64(nil), (*sm.Buckets)...)
418			} else if sm.Buckets != nil {
419				return nil, false // buckets only valid on histograms
420			}
421	
422			batch = append(batch, validatedSample{
423				key:     seriesKey(name, labels),
424				name:    name,
425				typ:     typ,
426				labels:  copyLabels(labels),
427				value:   value,
428				buckets: buckets,
429			})
430		}
431		return batch, true
432	}
433	
434	func validBuckets(buckets []float64) bool {
435		if len(buckets) == 0 {
436			return false
437		}
438		prev := math.Inf(-1)
439		for _, b := range buckets {
440			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
441				return false
442			}
443			prev = b
444		}
445		return true
446	}
447	
448	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
449	// values and non-object payloads for struct targets.
450	func strictDecode(data []byte, target any) bool {
451		dec := json.NewDecoder(bytes.NewReader(data))
452		dec.DisallowUnknownFields()
453		if err := dec.Decode(target); err != nil {
454			return false
455		}
456		var extra json.RawMessage
457		if err := dec.Decode(&extra); err != io.EOF {
458			return false
459		}
460		return true
461	}
462	
463	func handleMetricsGet(w http.ResponseWriter, r *http.Request, store *metricStore) {
464		values, err := url.ParseQuery(r.URL.RawQuery)
465		if err != nil {
466			writeAPIError(w, "invalid_query", http.StatusBadRequest)
467			return
468		}
469	
470		names := values["name"]
471		if len(names) == 0 || !identPattern.MatchString(names[0]) {
472			writeAPIError(w, "invalid_query", http.StatusBadRequest)
473			return
474		}
475	
476		selector := make(map[string]string)
477		for key, vals := range values {
478			if !strings.HasPrefix(key, "label.") {
479				continue
480			}
481			labelKey := strings.TrimPrefix(key, "label.")
482			if !identPattern.MatchString(labelKey) {
483				writeAPIError(w, "invalid_query", http.StatusBadRequest)
484				return
485			}
486			for _, v := range vals[1:] {
487				if v != vals[0] {
488					writeAPIError(w, "invalid_query", http.StatusBadRequest)
489					return
490				}
491			}
492			selector[labelKey] = vals[0]
493		}
494	
495		seriesList := store.query(names[0], selector)
496		w.Header().Set("Content-Type", "application/json; charset=utf-8")
497		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
498	}
499	
500	func writeAPIError(w http.ResponseWriter, code string, status int) {
501		w.Header().Set("Content-Type", "application/json; charset=utf-8")
502		w.WriteHeader(status)
503		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
504	}
505

