255	// ---- notification plan -----------------------------------------------------
256	
257	// deliveryOutput is one planned notification: the alert to send, the receiver
258	// resolved from the winning route, and the route that won.
259	type deliveryOutput struct {
260		AlertID  string `json:"alert_id"`
261		Receiver string `json:"receiver"`
262		RouteID  string `json:"route_id"`
263	}
264	
265	// notificationPlan evaluates alerts and routes against one consistent snapshot
266	// shared with metrics, alert rules, silences and inhibit rules. Only alerts
267	// that are firing and neither silenced nor inhibited participate. Each
268	// participating alert is delivered through the covering route with the
269	// smallest priority, ties broken by the smallest route id; participating
270	// alerts with no covering route are reported as unrouted.
271	func (s *metricStore) notificationPlan() ([]deliveryOutput, []string) {
272		s.mu.RLock()
273		defer s.mu.RUnlock()
274	
275		alerts := s.evalAlertsLocked()
276		// Routes are sorted by id, so scanning in order and replacing the winner
277		// only on a strictly smaller priority also resolves priority ties toward
278		// the smallest id.
279		routes := s.snapshotNotificationRoutesLocked()
280	
281		deliveries := make([]deliveryOutput, 0)
282		unrouted := make([]string, 0)
283		for _, al := range alerts {
284			if al.State != "firing" || al.Silenced || al.Inhibited {
285				continue
286			}
287			var best *notificationRoute
288			for _, rt := range routes {
289				if !containsString(rt.ruleIDs, al.ID) {
290					continue
291				}
292				if best == nil || rt.priority < best.priority {
293					best = rt
294				}
295			}
296			if best == nil {
297				unrouted = append(unrouted, al.ID)
298				continue
299			}
300			deliveries = append(deliveries, deliveryOutput{
301				AlertID:  al.ID,
302				Receiver: best.receiver,
303				RouteID:  best.id,
304			})
305		}
306	
307		// Alert evaluation already returns alerts sorted by id, but enforce the
308		// documented output order explicitly.
309		sort.Slice(deliveries, func(i, j int) bool { return deliveries[i].AlertID < deliveries[j].AlertID })
310		sort.Strings(unrouted)
311		return deliveries, unrouted
312	}
